// Weryfikacja podpisu żądania z kalkulatora (HMAC-SHA256) i deduplikacja po X-Event-Id.
// HMAC liczy poprzedni węzeł "Oblicz podpis (HMAC)" z sekretu wpisanego w jego polu Secret: ten kod nie używa require ani $env,
// więc nie wymaga żadnych zmian w konfiguracji serwera n8n.
const { headers, body, expectedHmac } = $input.first().json;
const reject = (reason, status) => [{ json: { send: false, status: status, reason: reason } }];
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Zabezpieczenie: dopóki w węźle Crypto jest sekret zastępczy lub zbyt krótki, nie przyjmujemy niczego (fail-closed).
const secret = String($node['Oblicz podpis (HMAC)'].parameter.secret || '');
if (secret === 'WKLEJ_SEKRET_TUTAJ' || secret.length < 16) return reject('sekret_nie_ustawiony', 500);

const timestamp = String(headers['x-timestamp'] || '');
if (!/^[0-9]{1,12}$/.test(timestamp)) return reject('zly_znacznik_czasu', 401);
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) return reject('przeterminowane', 401);

// Porównanie w stałym czasie (bez zdradzania, ile pierwszych znaków się zgadza).
const given = String(headers['x-signature'] || '');
const wanted = 'sha256=' + String(expectedHmac || '');
let diff = given.length ^ wanted.length;
for (let i = 0; i < wanted.length; i++) {
  diff |= (given.charCodeAt(i) || 0) ^ wanted.charCodeAt(i);
}
if (diff !== 0 || !expectedHmac) return reject('zly_podpis', 401);

// Dostarczanie jest "co najmniej raz": ten sam alert może przyjść dwa razy (X-Event-Id jest taki sam).
const eventId = String(headers['x-event-id'] || body.eventId || '');
const store = $getWorkflowStaticData('global');
const seen = Array.isArray(store.seen) ? store.seen : [];
if (eventId && seen.includes(eventId)) return [{ json: { send: false, status: 200, reason: 'duplikat' } }];
store.seen = [...seen, eventId].slice(-500);

// Tekst alertu: treść escapowana pod tryb HTML Telegrama, potem link do widoku konsultanta.
return [{ json: { send: true, status: 200, chatId: body.channel.target, text: esc(body.message) + '\n' + body.sessionUrl } }];
